const e=$json.body ?? $json;
const msg=e.whatsappInboundMessage ?? e.message ?? {};
if(e.type && e.type!== 'whatsapp.inbound_message.received') return [];
const incoming=String(msg.text?.body ?? msg.interactive?.button_reply?.title ?? msg.interactive?.list_reply?.title ?? '').trim();
const recipient=String(msg.from ?? '').trim();
const sender=String(msg.to ?? '').trim();
if(msg.type && msg.type!=='text' && msg.type!=='interactive') return [];
if(!incoming || !recipient || !sender || !/^\+?\d{8,15}$/.test(recipient)) return [];
const referral = msg.referral ?? msg.context?.referral ?? null;
const from_ad = Boolean(referral && (referral.source_type === 'ad' || referral.ctwa_clid || referral.source_id));
return [{json:{
  incoming,recipient,sender,msg_id:String(msg.id ?? e.id ?? ''),
  from_ad,
  ad_source_id:String(referral?.source_id ?? ''),
  ad_headline:String(referral?.headline ?? ''),
  ad_body:String(referral?.body ?? ''),
  ad_url:String(referral?.source_url ?? ''),
  ad_welcome_text:String(referral?.welcome_message?.text ?? '')
}}];

const RESERVAS_URL = 'https://reservas.checua.shop/';
const entrada = $('Normalizar mensaje YCloud').first().json;
const registros = $('Consultar control bot · Supabase').all().map(x=>x.json).filter(x => x && x.telefono);
const telefonoCanonico = String(entrada.recipient);
const registroActual = registros.filter(c => c.telefono === telefonoCanonico);
if (!registroActual.length || registroActual[0].bot_habilitado !== true || registroActual[0].atencion_humana === true) return [];

let planes = $('Consultar planes activos · Supabase').all().map(x => x.json);
if (planes.length === 1 && Array.isArray(planes[0])) planes = planes[0];
planes = planes.filter(p => p.activo !== false);
const promoGroupIds = new Set(planes.filter(p => p.es_grupo && String(p.nombre_plan ?? '').trim().toLowerCase() === 'promociones').map(p => Number(p.id_plan)));
planes = planes.filter(p => !promoGroupIds.has(Number(p.id_plan)) && !promoGroupIds.has(Number(p.id_plan_padre)));
const principales = planes.filter(p => p.id_plan_padre == null).sort((a,b) => Number(a.numero_plan ?? 9999)-Number(b.numero_plan ?? 9999));
if (!principales.length) throw new Error('No hay planes principales activos');
const cfg = $('Consultar imagen catálogo · Supabase').first().json;
const catalogoImagen = String(Array.isArray(cfg) ? cfg[0]?.valor ?? '' : cfg?.valor ?? '');
const norm = x => String(x ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
const nombre = p => String(p.nombre_plan ?? '').replace(/\s+/g,' ').trim();
const money = n => '$'+Number(n).toLocaleString('es-CO',{maximumFractionDigits:0});
const precio = p => p.precio_plan != null ? money(p.precio_plan) : 'Ver opciones';
const nl = String.fromCharCode(10);
const catalogNames = {
  1:'Senderismo en el Desierto', 2:'Desierto + Mina de Sal + Almuerzo',
  3:'Aventura en bicicleta', 4:'Senderismo + descanso en montaña',
  5:'Escápate a Nemocón', 6:'Buggies por Nemocón',
  7:'Retiro para parejas', 10:'Mapping nocturno',
  11:'Astroturismo', 12:'Picnic en el Desierto',
  13:'Nemocón Todo Incluido', 14:'Promo Senderismo + Mina',
  15:'Festival Halloween'
};
const shortName = p => catalogNames[Number(p.numero_plan)] || nombre(p).slice(0,40).trim();
const planEmoji = p => {
  const n=Number(p.numero_plan);
  const symbolByNumber = {1:'🥾',2:'🧂',3:'🚴',4:'🧖',5:'🏡',6:'🏎️',7:'💑',10:'🎆',11:'🔭',12:'🧺',13:'🏞️',14:'🎁',15:'🎃'};
  if(symbolByNumber[n]) return symbolByNumber[n];
  const name=norm(nombre(p));
  if(name.includes('bicicleta')) return '🚴';
  if(name.includes('buggy')||name.includes('buggies')) return '🏎️';
  if(name.includes('picnic')) return '🧺';
  if(name.includes('mina')) return '⛏️';
  if(name.includes('noche')||name.includes('nocturno')) return '🌙';
  if(name.includes('senderismo')) return '🥾';
  return '🌵';
};
const welcome = language => {
  const lines = principales.filter(p=>p.numero_plan!=null).map(p=>String(p.numero_plan)+'. '+planEmoji(p)+' '+shortName(p)+' · '+precio(p));
  const content = language==='en'
    ? ['🌵✨ *Welcome to Desierto de Checua!*','So happy you are here! 💛 Nature, adventures and unforgettable memories are waiting for you.','🎒 *Find your next adventure:*','💬 Which one catches your eye? Tell me the *number, name or price* and I will share the details. 😊']
    : language==='pt'
    ? ['🌵✨ *Bem-vindo ao Deserto de Checua!*','Que alegria ter você aqui! 💛 Natureza, aventura e lembranças especiais esperam por você.','🎒 *Escolha sua próxima aventura:*','💬 Qual chamou sua atenção? Diga o *número, nome ou preço* para saber mais. 😊']
    : ['🌵✨ *¡Bienvenido al Desierto de Checua!*','¡Qué alegría saludarte! 💛 Por aquí tenemos caminatas, aventura y planes especiales para desconectarte de la rutina.','🎒 *Encuentra tu próxima aventura:*','💬 ¿Cuál te llamó la atención? Dime su *número, nombre o precio* y te cuento qué incluye. 😊'];
  const [title,intro,heading,closing] = content;
  let out = title + nl + intro + nl + nl + heading;
  for(const line of lines){if((out+nl+line+nl+nl+closing).length<=1000)out+=nl+line;}
  return out+nl+nl+closing;
};
const msg = norm(entrada.incoming);
const store = $getWorkflowStaticData('global');
store.chatStates ??= {};
const prev = store.chatStates[entrada.recipient] ?? {};
const current = planes.find(p => Number(p.id_plan) === Number(prev.planId ?? registroActual[0]?.id_plan)) ?? null;
const hijos = padre => planes.filter(p => Number(p.id_plan_padre) === Number(padre.id_plan));
const group = p => Boolean(p.es_grupo) || hijos(p).length > 0;
const nmatch = msg.match(/^(?:plan\s*(?:numero|n)?\s*|el\s*plan\s*|el\s*|numero\s*)?(\d{1,2})$/) ?? msg.match(/\b(?:plan|numero)\s*(?:numero|n)?\s*(\d{1,2})\b/);
let chosen = null;
if (nmatch) {
  const n = Number(nmatch[1]);
  chosen = (current && group(current) && n>0 && !msg.includes("plan")) ? (hijos(current)[n-1] ?? null) : null;
  if (!chosen) chosen = principales.find(p=>Number(p.numero_plan)===n) ?? null;
}
if (!chosen) {
  const numbers = [...msg.matchAll(/(?:\$\s*)?(\d{2,3}(?:[., ]?\d{3})+|\d{4,7})/g)].map(m=>Number(m[1].replace(/[., ]/g,'')));
  const matches = planes.filter(p=>p.precio_plan!=null && numbers.includes(Number(p.precio_plan)));
  if (matches.length===1) chosen=matches[0];
}
if (!chosen && msg.length>2) {
  const pool = [...principales,...planes.filter(p=>p.id_plan_padre!=null)];
  const exact = pool.filter(p=>norm(nombre(p))===msg || msg.includes(norm(nombre(p))));
  if (exact.length===1) chosen=exact[0];
  if (!chosen) {
    const scored=pool.map(p=>({p,score:norm(nombre(p)).split(' ').filter(w=>w.length>3&&!['plan','desierto','checua','nemocon'].includes(w)&&msg.includes(w)).length})).sort((a,b)=>b.score-a.score);
    if(scored[0]?.score>0 && (!scored[1] || scored[0].score>scored[1].score)) chosen=scored[0].p;
  }
}
// A pauta pode incluir o plano no texto, título ou link do anúncio.
const fromAd = entrada.from_ad === true;
const adText = norm([entrada.ad_headline,entrada.ad_body,entrada.ad_welcome_text].filter(Boolean).join(' '));
if (fromAd && !chosen) {
  const pool = [...principales,...planes.filter(p=>p.id_plan_padre!=null)];
  const numbered = adText.match(/(?:plan|paquete|tour|paseo)\s*(?:numero\s*)?(\d{1,2})\b/);
  const urlNumber = String(entrada.ad_url||'').match(/(?:plan|tour|paseo)[=\/](\d{1,2})(?:\b|$)/i);
  if(numbered || urlNumber) {
    chosen=principales.find(p=>Number(p.numero_plan)===Number((numbered||urlNumber)[1])) || null;
  }
  if(!chosen && adText) {
    const full=pool.filter(p=>norm(nombre(p)).length>=8 && adText.includes(norm(nombre(p))));
    if(full.length===1) chosen=full[0];
    if(!chosen) {
      const ignored=new Set(['plan','desierto','checua','nemocon','aventura','experiencia','para','y','con','por','el','de','del','la','los','las','en','una','un','sal','todo']);
      const scored=pool.map(p=>{
        const terms=norm(nombre(p)).split(' ').filter(x=>x.length>3&&!ignored.has(x));
        const count=terms.filter(x=>adText.split(' ').includes(x)).length;
        return {p,count};
      }).sort((a,b)=>b.count-a.count);
      if(scored[0]?.count>=1 && (!scored[1] || scored[0].count>scored[1].count)) chosen=scored[0].p;
    }
  }
}
const explicitGreeting=/^(?:hola+|hol|ola+|buenas(?: dias| tardes| noches)?|buenos dias|buenas tardes|buenas noches|saludos|hello|hi|hey|good morning|good afternoon|good evening|bom dia|boa tarde|boa noite)(?:\s|$)/.test(msg);
const firstGreeting = registroActual[0].saludo_bot_enviado !== true;
const shouldGreet = firstGreeting || explicitGreeting;
const greetPlan = language => language==='en'
  ? 'Hi! 😊 It is great to hear from you. Here is what this experience includes:'
  : language==='pt'
  ? 'Olá! 😊 Que alegria receber sua mensagem. Veja o que inclui esta experiência:'
  : '¡Hola! 😊 Qué gusto saludarte. Mira lo que incluye esta experiencia:';
const catalogText = (language, withGreeting) => {
  const full=welcome(language);
  if(withGreeting) return full;
  const ix=full.indexOf('🎒 *');
  return ix>=0?full.slice(ix):full;
};
const infoRequest=/\b(informacion|info|incluye|inclui|incluido|descripcion|description|detalles|details|interesa|interesado|interesada|interested|conocer|saber|about|explicame|tell me)\b/.test(msg);
const languageGuess = /\b(hello|hi|good morning|good evening|show me|another tour|another plan|i want|i would like|how do i|what|where|when|how|can i|do you|book now|booking|yes please|thank you)\b/.test(msg) ? 'en' : /\b(ola|bom dia|boa tarde|boa noite|outro passeio|outro plano|quero|gostaria|obrigado|quanto custa|sim por favor)\b/.test(msg) ? 'pt' : null;
const lang = languageGuess || prev.lang || 'es';
const texts = {
  en:{hello:'Hello! 😊 Discover our tours:',choose:'✨ Which tour interests you? Reply with a number, name or price. 😊',group:'Available options:',which:'✨ Which buggy route interests you? Reply with its number or name.',cta:'✨ Would you like to book this tour or ask a question? 😊',book:'✨ *Booking your experience is easy!*\n\n1️⃣ Complete your booking details: '+RESERVAS_URL+'\n\n2️⃣ Pay the deposit. 💳\n\n📸 Send us a screenshot of your payment receipt and our team will confirm your reservation.\n\n🌵 Your next adventure starts here!',details:'Full descriptions are currently available in Spanish. Our team can help with details in English.'},
  pt:{hello:'Olá! 😊 Conheça nossos passeios:',choose:'✨ Qual passeio lhe interessa? Responda com número, nome ou preço. 😊',group:'Opções disponíveis:',which:'✨ Qual roteiro de buggy lhe interessa? Responda com o número ou nome.',cta:'✨ Gostaria de reservar este passeio ou tem alguma dúvida? 😊',book:'✨ *Reservar sua experiência é fácil!*\n\n1️⃣ Preencha seus dados: '+RESERVAS_URL+'\n\n2️⃣ Faça o pagamento do sinal. 💳\n\n📸 Envie a captura do comprovante de pagamento e nossa equipe confirmará sua reserva.\n\n🌵 Sua próxima aventura começa aqui!',details:'As descrições completas estão disponíveis em espanhol. Nossa equipe pode ajudar em português.'}
};
if (lang !== 'es') {
  const t=texts[lang];
  const hi=/^(hello|hi|hey|good morning|good afternoon|good evening|show me the tours|show me the plans|another tour|another plan|i want another plan|i want another tour|ola|bom dia|boa tarde|boa noite|outro passeio|outro plano|quero ver outro passeio)$/.test(msg);
  const confirm=/^(yes|yes please|sure|yeah|yep|book now|i want to book|i would like to book|how do i book|sim|sim por favor|claro|quero reservar|como reservar)$/.test(msg);
  const list=principales.map(p=>String(p.numero_plan??'')+'. '+nombre(p).slice(0,48)+' — '+precio(p));
  let answer='', picture='', selected=null;
  if((hi && !chosen && !fromAd) || (!current && !chosen && !confirm && !fromAd)) {
    answer=catalogText(lang,shouldGreet);
    picture=catalogoImagen;
    store.chatStates[entrada.recipient]={lang,updated:Date.now()};
  } else if(fromAd && !chosen && !confirm) {
    picture='';
    answer=(shouldGreet ? (lang==='en' ? 'Hello! 😊 Thanks for reaching out.\n\n' : 'Olá! 😊 Que bom receber sua mensagem.\n\n') : '')+(lang==='en' ? 'Which experience in our ad interested you? Tell me its name and I will share what is included. 🌵' : 'Qual experiência do nosso anúncio chamou sua atenção? Diga o nome e conto o que está incluído. 🌵');
  } else if(chosen && group(chosen)) {
    selected=chosen.id_plan;picture=String(chosen.imagen_url||catalogoImagen);
    answer=(shouldGreet ? greetPlan(lang)+'\n\n' : '')+'🚙 *'+nombre(chosen)+'*\n'+t.group+'\n'+hijos(chosen).map((p,i)=>(i+1)+'. '+nombre(p)+' — '+precio(p)).join('\n')+'\n\n'+t.which;
    store.chatStates[entrada.recipient]={planId:chosen.id_plan,lang,updated:Date.now()};
  } else if(chosen) {
    selected=chosen.id_plan;picture=String(chosen.imagen_url||'');
    const description=[String(chosen.descripcion_basica??'').trim(),String(chosen.descripcion_detallada??'').trim()].filter(Boolean).join('\n\n');
    const title=(shouldGreet ? greetPlan(lang)+'\n\n' : '')+'🌵 *'+nombre(chosen)+'*\n💰 '+precio(chosen)+'\n\n'+t.details+'\n'+description;
    const closing='\n\n'+t.cta;
    answer=title.length+closing.length>1024 ? title.slice(0,1023-closing.length).trimEnd()+'…'+closing : title+closing;
    store.chatStates[entrada.recipient]={planId:chosen.id_plan,lang,updated:Date.now()};
  } else if(confirm && current && !group(current)) {
    selected=current.id_plan;answer=t.book;
  } else if(current && group(current)) {
    picture=String(current.imagen_url||catalogoImagen);
    answer=(shouldGreet ? greetPlan(lang)+'\n\n' : '')+'🚙 *'+nombre(current)+'*\n'+t.group+'\n'+hijos(current).map((p,i)=>(i+1)+'. '+nombre(p)+' — '+precio(p)).join('\n')+'\n\n'+t.which;
  } else if(current) {
    answer=(shouldGreet ? greetPlan(lang)+'\n\n' : '')+'🌵 *'+nombre(current)+'* — '+precio(current)+'\n'+t.cta;
  } else {
    answer=catalogText(lang,shouldGreet);picture=catalogoImagen;
  }
  const bookingIntention = confirm && (current && !group(current) || /^(i want to book|how do i book|how to book|book now|quero reservar|como reservar)$/.test(msg));
  const uncertain = !hi && !bookingIntention && !(chosen && infoRequest) && (/[?¿]/.test(String(entrada.incoming)) || /^(what|how|where|when|can i|do you|quanto|onde|quando|posso|tem)\b/.test(msg));
  if (uncertain) {
    picture='';
    answer = lang==='en' ? '😊 Our team will answer your question personally. An advisor will take over this conversation.' : '😊 Nossa equipe responderá sua pergunta pessoalmente. Um atendente continuará esta conversa.';
  }
  const stage = bookingIntention ? 'como_reservar' : (chosen ? 'descripcionincluye' : (hi || fromAd ? 'saludo' : (registroActual[0]?.etapaconversacion || 'saludo')));
  return [{json:{to:entrada.recipient,from:entrada.sender,image_url:picture,image_caption:answer.slice(0,1024),response_text:answer,planId:(stage==='saludo' && !chosen) ? null : (selected ?? current?.id_plan ?? null),etapa:stage,handoff:Boolean(uncertain || bookingIntention)}}];
}
const yes = /^(si|simon|sisas|sip|sipi|seh|claro|listo|quiero reservar|reservar|me interesa|de una|dale|ok|bueno)(\b|$)/.test(msg);
const greeting = /^(hola+|hol|ola+|buenas|buenos dias|buenas tardes|buenas noches|hey|catalogo|planes|ver planes|menu|promociones|promocion|ofertas)[!. ]*$/.test(msg) || /^(muestrame|quiero ver|ver) (todos )?(los )?planes$/.test(msg) || /^(otro|otra|otros|otro plan|otra opcion|quiero ver otro plan|quiero otro plan|ver otro plan|ver otros planes|quiero ver otros planes|muestrame otros planes|conocer otro plan|quiero conocer otro plan|no quiero este plan)$/.test(msg);
// Cabe en una única imagen con caption de hasta 1024 caracteres SIN cortar el cierre comercial.
const fit = (intro, lines, closing, max=1024) => {
  let result=intro;
  for(const line of lines) {
    if((result+'\n'+line+'\n\n'+closing).length>max) break;
    result+='\n'+line;
  }
  return result+'\n\n'+closing;
};
const directBooking=/^(quiero reservar|deseo reservar|como reservar|como reservo|quiero hacer una reserva|vamos a reservar|reservar)$/.test(msg);
let response='', image='', planId=null, sentBookingMessage=false;
if (greeting && !chosen && !fromAd) {
  image=catalogoImagen;
  response=catalogText('es',shouldGreet);
  store.chatStates[entrada.recipient]={updated:Date.now()};
 } else if (fromAd && !chosen && !directBooking) {
  response=(shouldGreet ? '¡Hola! 😊 Qué gusto saludarte.\n\n' : '')+'Veo que llegaste desde uno de nuestros anuncios. ¿Qué experiencia te llamó la atención? Dime su nombre y con gusto te cuento qué incluye. 🌵';
} else if (chosen && group(chosen)) {
  const options=hijos(chosen);
  store.chatStates[entrada.recipient]={planId:chosen.id_plan,updated:Date.now()};
  planId=chosen.id_plan;
  image=String(chosen.imagen_url ?? catalogoImagen);
  const intro=(shouldGreet ? greetPlan('es')+'\n\n' : '')+'🚙 *'+nombre(chosen)+'*\nEstas son nuestras opciones:';
  response=fit(intro,options.map((p,i)=>String(i+1)+'. '+nombre(p)+' — '+precio(p)),'✨ ¿Qué recorrido de Buggies te interesa? Dime su nombre o número.');
} else if(chosen) {
  store.chatStates[entrada.recipient]={planId:chosen.id_plan,updated:Date.now()};
  planId=chosen.id_plan;
  image=String(chosen.imagen_url ?? '');
  const titulo=(shouldGreet ? greetPlan('es')+'\n\n' : '')+'🌵 *'+nombre(chosen)+'*\n💰 '+precio(chosen)+' por persona (ver condiciones)';
