  const descripcion=[String(chosen.descripcion_basica??'').trim(),String(chosen.descripcion_detallada??'').trim()].filter(Boolean).join('\n\n📋 *Detalles:*\n');
  const espacio=Math.max(0,1024-titulo.length-cta.length-5);
