} else {
  image=String(current.imagen_url??'');
  response=(shouldGreet ? greetPlan('es')+'\n\n' : '')+'🌵 *'+nombre(current)+'* — '+precio(current)+'\n¿Quieres reservarlo o conocer otro plan? 😊';
