const bookingRequested = sentBookingMessage;
const isQuestion = /[?¿]/.test(String(entrada.incoming)) || /^(que|como|cuando|donde|cuanto|cual|tienen|puedo|hay|me puedes|what|how|when|where|can i|do you|quanto|onde|quando|posso|tem)\b/.test(msg);
const needsHuman = !greeting && !bookingRequested && !(chosen && infoRequest) && (isQuestion || /\b(asesor|humano|humana|persona real|hablar con alguien|necesito ayuda|no entiendo|operador|support agent|human agent|talk to a person|atendente|falar com alguem)\b/.test(msg));
