// El nodo YCloud de imagen debe usar response_text como caption y NO enviar luego texto adicional.
return [{json:{to:entrada.recipient,from:entrada.sender,image_url:image,image_caption:response,response_text:response,planId:(etapa==='saludo' && !chosen) ? null : (planId ?? current?.id_plan ?? null),etapa,handoff}}];

